INSERT INTO CRM_BOARD_MGT 
(
	SEQ, TITLE, CONTENT, CNT, ATTACH_SEQ, REG_DATE, REG_ID, BOARD_GBN, WORK_TYPE, WORK_TYPE2, NOTICE_NUM, IMP_YN, DEADLINE, HIGHLIGHT_WORDS
) 
VALUES 
(
	#{seq}, #{title}, #{content}, '0', #{attach_seq}, SYSDATE, #{reg_id}, #{board_gbn}, #{work_type}, #{work_type2}, #{notice_num}, #{imp_yn}, #{deadline}, #{highlight_words}
)


INSERT INTO CRM_NOTICE_ACCESS
(
	SEQ, NOTICE_SEQ, CRM_CODE, ALL_OPEN_YN
) 
VALUES 
(
	MAX_NOTICE_ACCESS_NO.NEXTVAL, #{notice_seq}, #{crm_code}, #{all_open_yn}
)

mapper.update:

UPDATE CRM_BOARD_MGT SET 
	TITLE = #{title}
	,CONTENT = #{content}
	,ATTACH_SEQ = #{attach_seq}
	,UPD_DATE = SYSDATE
	,UPD_ID = #{reg_id}
	,WORK_TYPE = #{work_type}
	,WORK_TYPE2 = #{work_type2}
	,IMP_YN = #{imp_yn}
	,DEADLINE = #{deadline}
	,HIGHLIGHT_WORDS = #{highlight_words}
WHERE
	SEQ = #{seq}
AND
	BOARD_GBN = #{board_gbn}


UPDATE CRM_BOARD_MGT SET
	CNT = CNT+1
WHERE 
	SEQ = #{seq}
AND
	BOARD_GBN = #{board_gbn}

